async function runtimeCall(action,data={}){const r=await fetch('/api/runtime/'+action,{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+governedToken},body:JSON.stringify({tenant:'scholarion',course:'AIM310',...data})});const d=await r.json();if(!r.ok)throw Error(d.error);return d;}
async function runtimeLoad(){const d=await runtimeCall('list');const n=document.getElementById('runtime-runs');if(!n)return;n.innerHTML=`<p>${esc(d.mode)}</p>${d.runs.map(r=>`<article class="callout"><h3>${esc(r.args.title)}</h3><p>${esc(r.args.body)}</p><p>Demo · ${esc(r.owner)} · ${esc(r.state)} · Version ${r.version}</p>${d.role==='instructor'&&r.state==='awaiting_approval'?['approve','reject'].map(a=>`<button class="button secondary" data-runtime="${a}" data-id="${r.id}" data-version="${r.version}">${a}</button>`).join(''):''}${r.state==='approved'?`<button class="button" data-runtime="resume" data-id="${r.id}" data-version="${r.version}">Execute approved action</button>`:''}${r.result_id?`<p>Saved support record: ${esc(r.result_id)} · <a href="#help">Open support requests</a></p>`:''}</article>`).join('')||'<p>No saved runs.</p>'}`;}
const beforeRuntime=render;render=function(){if(location.hash==='#agent-runtime'){document.getElementById('app').innerHTML=integratedShell('agent-runtime',heading('Agent action runner','Pre-launch · Demo · Persistent approval and resume')+`<section class="card prose"><p>This local tool creates a support request only after instructor approval. No external service or AI model is called. Do not enter secrets, payment or identity documents.</p><button class="button secondary" data-runtime="refresh">Refresh runs</button><p id="runtime-status" role="status"></p></section><section class="card prose"><h2>Propose support request</h2><form id="runtime-propose"><label>Title<input name="title" maxlength="150" required></label><label>Details<textarea name="body" maxlength="5000" required></textarea></label><button class="button">Save for approval</button></form></section><section class="card prose" id="runtime-runs">Connect to load saved runs.</section>`,model.role);bind();if(governedToken)runtimeLoad().catch(e=>document.getElementById('runtime-status').textContent=e.message);}else beforeRuntime();const nav=document.querySelector('aside nav')||document.querySelector('aside');if(nav&&!nav.querySelector('[href="#agent-runtime"]'))nav.insertAdjacentHTML('beforeend','<a href="#agent-runtime">Agent action runner</a>');};
document.addEventListener('submit',async e=>{if(!['runtime-connect','runtime-propose'].includes(e.target.id))return;e.preventDefault();try{const f=e.target,d=Object.fromEntries(new FormData(f));if(f.id==='runtime-connect'){governedToken=d.token;document.getElementById('runtime-runs').textContent='Loading authorized runs…';}else{f.dataset.key ||=crypto.randomUUID();await runtimeCall('propose',{tool:'create_support_request',args:d,request_key:f.dataset.key});delete f.dataset.key;}f.reset();await runtimeLoad();}catch(err){document.getElementById('runtime-status').textContent=err.message;}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-runtime]');if(!b)return;try{if(b.dataset.runtime!=='refresh')await runtimeCall(b.dataset.runtime,{id:b.dataset.id,version:Number(b.dataset.version)});await runtimeLoad();}catch(err){document.getElementById('runtime-status').textContent=err.message;}});render();
